using Xunit;

namespace Calendario.Tests;

public class LeapTests
{
    [InlineData(1996, true)]   // divisible entre 4
    [InlineData(1997, false)]  // no divisible entre 4
    [InlineData(1900, false)]  // divisible entre 100, pero no entre 400
    [InlineData(2000, true)]   // divisible entre 400
    [InlineData(2024, true)]
    [InlineData(2100, false)]
    [Theory]
    public void EsBisiesto(int year, bool expected) =>
        Assert.Equal(expected, Leap.EsBisiesto(year));
}

